<script setup>
import ReportStamp from './ReportStamp.vue';
// Native-style mobile composition adapted from MDS DashboardPageMobile/ListPageMobile.
import {ref} from 'vue';import {s,title,canAdmin,canEdit,isSuper,nav,run,navigate,selectEvent,showEventList,reports,number,dateText,roleNames,exportExcel,exportPng,insights,loadRows,editRow,setRole,saveEvent} from './store';
import MMobileTopBar from './mobile/MMobileTopBar.vue';import MMobileBottomNav from './mobile/MMobileBottomNav.vue';import ReportFilters from './ReportFilters.vue';import ChartPanel from './ChartPanel.vue';import KpiCard from './KpiCard.vue';import TargetsPanel from './TargetsPanel.vue';import SettingsFields from './SettingsFields.vue';import ImportFields from './ImportFields.vue';import MemberImport from './MemberImport.vue';
const more=ref(false),filters=ref(false);const items=[{key:'tong-quan',label:'Tổng quan',icon:'home'},{key:'du-lieu',label:'Dữ liệu',icon:'list'},{key:'nguon-du-lieu',label:'Nhập liệu',icon:'upload'},{key:'thanh-vien',label:'Thành viên',icon:'users'},{key:'more',label:'Thêm',icon:'menu-2'}];
function go(key){if(key==='more'){more.value=true;return;}more.value=false;run(()=>navigate(key));}
function back(){if(more.value){more.value=false;return;}if(s.route!=='tong-quan'){go('tong-quan');return;}run(()=>showEventList());}
</script><template><div class="mds-mobile-app relative flex h-full flex-col overflow-hidden"><MMobileTopBar :title="more?'Thêm':title" back-label="Quay lại" show-more @back="back" @more="more=!more"/><main class="scroll-region page-body stack"><div v-if="s.error" role="alert" class="error">{{s.error}}</div><div v-if="s.message" role="status" class="notice">{{s.message}}</div><progress v-if="s.busy" aria-label="Đang xử lý"/>
<template v-if="more"><section class="card stack"><h2>{{s.user.name}}</h2><p class="muted">{{s.user.email}}</p><MButton variant="secondary" @click="run(()=>showEventList())">Chọn sự kiện</MButton><MButton variant="primary" v-if="isSuper" @click="s.dialog='new-event'">Tạo sự kiện</MButton><MButton variant="secondary" @click="more=false;run(()=>navigate('muc-tieu'))">Thiết lập sự kiện</MButton><MButton v-if="canAdmin" variant="secondary" @click="more=false;run(()=>navigate('nhat-ky'))">Nhật ký</MButton><MButton variant="secondary" @click="s.appearance=true">Giao diện</MButton><MButton variant="secondary" @click="s.dialog='account'">Tài khoản & mật khẩu</MButton></section></template>
<template v-else><label class="field">Sự kiện<MCombobox :model-value="s.event?.id" :options="s.events.map(e=>({value:e.id,label:e.name}))" @update:model-value="run(()=>selectEvent($event))"/></label><p class="muted">Quyền hiện tại: {{roleNames[s.event?.role]||'Viewer'}}</p><MEmptyState v-if="!s.event" type="initial" title="Chọn sự kiện để bắt đầu"/>
<template v-else-if="s.route==='tong-quan'"><div class="row"><MButton variant="secondary" @click="filters=!filters">{{filters?'Ẩn bộ lọc':'Bộ lọc'}}</MButton><MButton variant="secondary" :disabled="s.reportBusy||!s.report" :loading="s.busy" @click="run(exportExcel)">Xuất Excel</MButton><MButton variant="secondary" :disabled="s.reportBusy||!s.report" :loading="s.busy" @click="run(exportPng)">Xuất ảnh</MButton></div><ReportFilters v-if="filters"/><MTabs :model-value="s.table?'table':'chart'" :tabs="[{key:'chart',label:'Dashboard'},{key:'table',label:'Bảng số liệu'}]" @update:model-value="s.table=$event==='table'"/><MCombobox v-model="s.selected" multiple :options="reports" placeholder="Chọn báo cáo"/><MCheckbox v-model="s.showPercent" label="Hiển thị % trên biểu đồ"/><div v-if="s.reportBusy" role="status" class="row card"><MSpinner/>Đang cập nhật số liệu…</div><div v-else-if="s.report" data-report class="stack"><ReportStamp/><div class="grid grid-cols-2 gap-4"><KpiCard v-for="kind in ['total','completion','clevel','ratio']" :key="kind" :kind="kind"/></div><p v-if="s.report.current.targetSum!==s.report.current.target" class="notice">Mục tiêu chi tiết {{number(s.report.current.targetSum)}} khác tổng mục tiêu {{number(s.report.current.target)}}.</p><ChartPanel mobile title="Hình thức tham dự" :rows="s.report.current.modes" :table="s.table"/><ChartPanel v-if="s.selected.includes('positions')" mobile title="Cơ cấu chức vụ" :rows="s.report.current.positions" :table="s.table" pie/><ChartPanel v-if="s.selected.includes('sizes')" mobile title="Quy mô doanh nghiệp" :rows="s.report.current.sizes" :table="s.table"/><ChartPanel v-if="s.selected.includes('trend')" mobile title="Xu hướng đăng ký" :rows="s.report.current.trend.map(r=>({...r,label:dateText(r.label),percent:s.report.current.total?r.count/s.report.current.total*100:0}))" :table="s.table"/><template v-if="s.selected.includes('sources')"><label class="field">Chiều nguồn khách<MCombobox v-model="s.dimension" :options="s.report.sourceDimensions.map(d=>({value:d.name,label:d.name}))"/></label><ChartPanel mobile :title="s.dimension||'Nguồn khách'" :rows="s.report.current.sourceBreakdowns.find(d=>d.name===s.dimension)?.values||[]" :table="s.table"/></template><TargetsPanel v-if="s.selected.includes('targets')" mobile/><section class="card stack"><h3>Nhận xét từ Gemini</h3><MButton variant="secondary" :loading="s.busy" @click="run(insights)">Phân tích số liệu</MButton><template v-if="s.insight"><p>{{s.insight.summary}}</p><p v-for="o in s.insight.observations" :key="o">{{o}}</p></template></section></div></template>
<template v-else-if="s.route==='thanh-vien'"><MemberImport/><section class="card mobile-list"><article v-for="m in s.members" :key="m.id"><h3>{{m.name}}</h3><p>{{m.email}}</p><div class="row mt-3"><MSelect v-if="isSuper" :model-value="m.role" :options="[{value:'editor',label:'Editor'},{value:'admin',label:'Admin'}]" @update:model-value="run(()=>setRole(m,$event))"/><span v-else>{{roleNames[m.role]}}</span><MButton v-if="isSuper||(canAdmin&&m.role==='editor')" variant="link" @click="s.editMember=m;s.dialog='remove-member'">Thu hồi quyền</MButton></div></article><MEmptyState v-if="!s.members.length" type="initial" title="Chưa cấp quyền chỉnh sửa"/></section></template>
<template v-else-if="s.route==='du-lieu'"><label class="field">Tìm đăng ký<MInput v-model="s.query" placeholder="Tên, email, công ty, tracking"/></label><MButton variant="secondary" @click="s.page=1;run(loadRows)">Tìm kiếm</MButton><section class="card mobile-list"><article v-for="r in s.rows" :key="r.id"><h3>{{r.name||'Chưa có tên'}}</h3><dl><dt>Công ty</dt><dd>{{r.company||'—'}}</dd><dt>Chức vụ</dt><dd>{{r.position||'—'}}</dd><dt>Ngày submit</dt><dd>{{dateText(r.submitted_at)}}</dd><dt>Hình thức</dt><dd>{{({online:'Online',offline:'Offline',both:'Cả hai'})[r.attendance_mode]||'Chưa xác định'}}</dd></dl><MButton v-if="canEdit" variant="secondary" @click="editRow(r)">Chỉnh sửa</MButton></article><MEmptyState v-if="!s.rows.length" type="no-result" title="Không có đăng ký phù hợp"/></section><div class="row justify-between"><MButton variant="secondary" :disabled="s.page===1" @click="s.page--;run(loadRows)">Trước</MButton><span>{{number(s.rowTotal)}} dòng</span><MButton variant="secondary" :disabled="s.page*50>=s.rowTotal" @click="s.page++;run(loadRows)">Sau</MButton></div></template>
<ImportFields v-else-if="s.route==='nguon-du-lieu'"/><SettingsFields v-else-if="s.route==='muc-tieu'"/><section v-else-if="s.route==='nhat-ky'" class="card mobile-list"><p v-if="!canAdmin">Bạn không có quyền xem nhật ký.</p><article v-for="(a,i) in canAdmin?s.audit:[]" :key="i">{{dateText(a.created_at)}} · {{a.name}} · {{a.action}}</article></section></template></main>
<footer v-if="!more&&s.route==='muc-tieu'&&canEdit" class="sticky-actions"><MButton variant="secondary" @click="run(()=>selectEvent(s.event.id))">Hủy</MButton><MButton variant="primary" :loading="s.busy" @click="run(saveEvent)">Lưu</MButton></footer><MMobileBottomNav :items="items" :active="more?'more':s.route" @select="go"/></div></template>
